package fr.roadguard.app;
import android.media.session.MediaController;
import android.app.*;import android.content.*;import android.media.session.*;import android.os.*;import android.view.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.util.*;import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class)
@Config(sdk={26,36},shadows={SpotifyRuntimeTest.ControllerState.class})
@LooperMode(LooperMode.Mode.PAUSED)
public class MobileAudioRuntimeTest {
  Application app;final List<MediaSession> sessions=new ArrayList<>();
  @Before public void setup(){app=RuntimeEnvironment.getApplication();app.getSharedPreferences("MainActivity",0).edit().clear().commit();app.getSharedPreferences("roadguard_equalizer",0).edit().clear().commit();SpotifyRuntimeTest.ControllerState.packages.clear();SpotifyRuntimeTest.ControllerState.states.clear();}
  @After public void cleanup(){for(MediaSession s:sessions)s.release();}
  MediaController controller(String pkg,int state,long actions){MediaSession s=new MediaSession(app,"mobile"+sessions.size());sessions.add(s);MediaController c=s.getController();SpotifyRuntimeTest.ControllerState.packages.put(c,pkg);SpotifyRuntimeTest.ControllerState.states.put(c,new PlaybackState.Builder().setState(state,0,1).setActions(actions).build());return c;}
  @Test public void pinnedPlayerNeverFallsBackToAnotherPlayingApp(){MediaController spotify=controller(SpotifyControls.PACKAGE,PlaybackState.STATE_PAUSED,PlaybackState.ACTION_PLAY),other=controller("org.videolan.vlc",PlaybackState.STATE_PLAYING,PlaybackState.ACTION_PAUSE);assertSame(spotify,MusicSources.select(Arrays.asList(other,spotify),SpotifyControls.PACKAGE));assertNull(MusicSources.select(Collections.singletonList(other),SpotifyControls.PACKAGE));}
  @Test public void automaticModeFollowsPlayingSession(){MediaController paused=controller(SpotifyControls.PACKAGE,PlaybackState.STATE_PAUSED,PlaybackState.ACTION_PLAY),playing=controller("org.videolan.vlc",PlaybackState.STATE_PLAYING,PlaybackState.ACTION_PAUSE);assertSame(playing,MusicSources.select(Arrays.asList(paused,playing),MusicSources.AUTO));}
  @Test public void otherPlayersUseOnlyTheirAdvertisedCommands(){MediaController vlc=controller("org.videolan.vlc",PlaybackState.STATE_PLAYING,PlaybackState.ACTION_PAUSE);assertTrue(SpotifyControls.supportedPlayer(vlc,"toggle"));assertTrue(SpotifyControls.sendPlayer(vlc,"toggle"));assertFalse(SpotifyControls.supportedPlayer(vlc,"next"));assertFalse(SpotifyControls.sendPlayer(vlc,"next"));assertFalse(SpotifyControls.sendPlayer(vlc,"unknown"));assertFalse(SpotifyControls.send(vlc,"toggle"));}
  @Test public void selectedSourcePersistsAndDefaultsToExistingSpotify(){assertEquals(SpotifyControls.PACKAGE,MusicSources.selected(app));app.getSharedPreferences("MainActivity",0).edit().putString("music_source","org.videolan.vlc").commit();assertEquals("org.videolan.vlc",MusicSources.selected(app));assertNull(MusicSources.current(app));}
  @Test public void savedCurveUsesLogarithmicallyNearestHardwareFrequency(){assertEquals(0,AudioCurve.nearest(20));assertEquals(5,AudioCurve.nearest(1000));assertEquals(9,AudioCurve.nearest(22000));int[] gains={100,200,300,400,500,600,700,800,900,1000};assertEquals(600,AudioCurve.gain(gains,1000,false,-1500,1500));}
  @Test public void headroomRemovesLargestPositiveGainAndHardwareLimitsAreRespected(){int[] curve=new int[10];curve[5]=600;assertEquals(0,AudioCurve.gain(curve,1000,true,-1500,1500));assertEquals(-600,AudioCurve.gain(curve,31,true,-1500,1500));assertEquals(300,AudioCurve.gain(curve,1000,false,-300,300));curve[5]=Integer.MAX_VALUE;assertEquals(1200,AudioCurve.gain(curve,1000,false,-1500,1500));}
  @Test public void neutralAndPresetCurvesAreBounded(){for(int[] preset:AudioCurve.CURVES){assertEquals(10,preset.length);for(int v:preset)assertTrue(v>=-1200&&v<=1200);}assertEquals(0,AudioCurve.gain(AudioCurve.CURVES[0],1000,true,-1500,1500));}
  static void seekBars(View v,List<SeekBar> result){if(v instanceof SeekBar)result.add((SeekBar)v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)seekBars(((ViewGroup)v).getChildAt(i),result);}
  @Test public void studioOpensWithoutHardwareAndKeepsUserCurve(){org.robolectric.android.controller.ActivityController<Activity> c=Robolectric.buildActivity(Activity.class).setup();AlertDialog d=null;try{Activity a=c.get();MobileAudioStudio.show(a);d=(AlertDialog)org.robolectric.shadows.ShadowDialog.getLatestDialog();assertTrue(d.isShowing());List<SeekBar> bars=new ArrayList<>();seekBars(d.getWindow().getDecorView(),bars);assertEquals(11,bars.size());bars.get(0).setProgress(1500);assertEquals(300,app.getSharedPreferences("roadguard_equalizer",0).getInt("gain_0",0));d.dismiss();MobileAudioStudio.show(a);d=(AlertDialog)org.robolectric.shadows.ShadowDialog.getLatestDialog();bars.clear();seekBars(d.getWindow().getDecorView(),bars);assertEquals(1500,bars.get(0).getProgress());assertFalse(app.getSharedPreferences("roadguard_equalizer",0).getBoolean("enabled",false));}finally{if(d!=null)d.dismiss();c.pause().stop().destroy();}}
}
